def f(x):
 if x==1: raise StopIteration("callback")
 return x
i=map(f,[1,2],strict=True)
try: next(i)
except StopIteration as e: print(str(e))
print(next(i))

def f(x):
 if x==1: raise ValueError("callback")
 return x
i=map(f,[1,2])
try: next(i)
except ValueError as e: print(str(e))
print(next(i))

