class S:
 def __init__(self,n): self.n=n
 def __iter__(self):
  print("iter",self.n)
  return iter([self.n])
class Strict:
 def __bool__(self):
  print("strict")
  return True
i=map(pow,S(2),S(3),strict=Strict())
print("created")
print(list(i))

class Strict:
 def __bool__(self):
  print("strict")
  return True
try: map(strict=Strict())
except TypeError as e: print(str(e))

class A:
 def __getitem__(self,i):
  if i==2: raise IndexError
  return -i
print(list(map(abs,A())))

class I:
 def __init__(self): self.n=0
 def __iter__(self): return self
 def __next__(self):
  self.n+=1
  if self.n==1: raise StopIteration("source")
  return self.n
i=map(abs,I())
try: next(i)
except StopIteration as e: print(str(e))
print(next(i))

class I:
 def __init__(self): self.n=0
 def __iter__(self): return self
 def __next__(self):
  self.n+=1
  if self.n==1: raise ValueError("source")
  return -self.n
i=map(abs,I(),strict=True)
try: next(i)
except ValueError as e: print(str(e))
print(next(i))

class I:
 def __iter__(self): return self
 def __next__(self): raise LookupError("probe")
list(map(pow,[],I(),strict=True))

class A:
 def __iter__(self):
  print("iter")
  raise ValueError("acquire")
map(abs,A())
